package demo.pharma.supplier;
import demo.pharma.catalog.RecordStatus;import demo.pharma.common.exception.*;import demo.pharma.common.web.PageResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import lombok.*;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/suppliers") @RequiredArgsConstructor public class SupplierController {private final SupplierRepository repo;record Request(@NotBlank String supplierCode,@NotBlank String companyName,String contactPerson,String phone,String email,String address,String gstin,String paymentTerms,RecordStatus status){}record View(UUID id,String supplierCode,String companyName,String phone,RecordStatus status){}@GetMapping @PreAuthorize("hasAuthority('SUPPLIER_VIEW')") PageResponse<View> list(@RequestParam(required=false)String search,@PageableDefault(size=20,sort="companyName")Pageable p){return PageResponse.of(repo.findAll((r,q,b)->search==null?b.conjunction():b.or(b.like(b.lower(r.get("companyName")),"%"+search.toLowerCase()+"%"),b.like(b.lower(r.get("supplierCode")),"%"+search.toLowerCase()+"%"),b.like(b.lower(r.get("phone")),"%"+search.toLowerCase()+"%")),p).map(this::view));}@PostMapping @PreAuthorize("hasAuthority('SUPPLIER_CREATE')") View create(@Valid @RequestBody Request r){if(repo.existsBySupplierCodeIgnoreCase(r.supplierCode()))throw new BusinessException("Supplier code already exists");Supplier s=new Supplier();apply(s,r);return view(repo.save(s));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('SUPPLIER_VIEW')")View get(@PathVariable UUID id){return view(find(id));}@PutMapping("/{id}")@PreAuthorize("hasAuthority('SUPPLIER_UPDATE')")View update(@PathVariable UUID id,@Valid@RequestBody Request r){Supplier s=find(id);apply(s,r);return view(repo.save(s));}@DeleteMapping("/{id}")@PreAuthorize("hasAuthority('SUPPLIER_UPDATE')")void delete(@PathVariable UUID id){Supplier s=find(id);s.setStatus(RecordStatus.INACTIVE);repo.save(s);}@SuppressWarnings("unused")private Supplier find(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Supplier",id));}private void apply(Supplier s,Request r){s.setSupplierCode(r.supplierCode());s.setCompanyName(r.companyName());s.setContactPerson(r.contactPerson());s.setPhone(r.phone());s.setEmail(r.email());s.setAddress(r.address());s.setGstin(r.gstin());s.setPaymentTerms(r.paymentTerms());s.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());}private View view(Supplier s){return new View(s.getId(),s.getSupplierCode(),s.getCompanyName(),s.getPhone(),s.getStatus());}}
